"use client";
import React, { useState, useEffect } from 'react';
import Sidebar from '@/components/Sidebar';
import ChatInterface from '@/components/ChatInterface';
import AvatarView from '@/components/AvatarView';
import ActionPanel from '@/components/ActionPanel';
import ActionIssuesPanel from '@/components/ActionIssuesPanel';
import MemoryExplorer from '@/components/MemoryExplorer';
import LivestreamDashboard from '@/components/LivestreamDashboard';
import SettingsPanel from '@/components/SettingsPanel';
import StatsPanel from '@/components/StatsPanel';
import DrawLab from '@/components/DrawLab';
import { Menu, X } from 'lucide-react';

export default function Home() {
  const [activeTab, setActiveTab] = useState('chat'); // 'chat' | 'memories' | 'profile' | 'settings'
  const [isTalking, setIsTalking] = useState(false);
  const [emotion, setEmotion] = useState("neutral");
  const [agentState, setAgentState] = useState("");
  const [isThinking, setIsThinking] = useState(false);
  const [agentMode, setAgentMode] = useState('normal'); // 'normal' | 'stream' | 'dev'
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // Load mode from localStorage on mount
  useEffect(() => {
    const savedMode = localStorage.getItem('agent_mode');
    if (savedMode) setAgentMode(savedMode);
  }, []);

  // Save mode when changed
  const handleModeChange = (mode: string) => {
    setAgentMode(mode);
    localStorage.setItem('agent_mode', mode);
  };

  // Close mobile menu when tab changes
  const handleTabChange = (tab: string) => {
    setActiveTab(tab);
    setMobileMenuOpen(false);
  };

  return (
    <main className="flex h-screen w-full overflow-hidden bg-[#0f0f12] text-white">
      {/* Mobile Menu Button */}
      <button
        className="md:hidden fixed top-3 left-3 z-50 p-2 rounded-xl glass"
        onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
      >
        {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
      </button>

      {/* 1. Sidebar - Desktop: always visible, Mobile: overlay */}
      <div className="hidden md:block">
        <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />
      </div>

      {/* Mobile Sidebar Overlay */}
      {mobileMenuOpen && (
        <div className="md:hidden fixed inset-0 z-40">
          <div className="absolute inset-0 bg-black/60" onClick={() => setMobileMenuOpen(false)} />
          <div className="absolute left-0 top-0 h-full z-50">
            <Sidebar activeTab={activeTab} setActiveTab={handleTabChange} />
          </div>
        </div>
      )}

      {/* 2. Main Content Area */}
      <div className="flex-1 flex max-w-full relative">

        {/* Avatar Panel (Right Side by default or Split) */}
        {/* Let's do a split view: Left Chat, Right Avatar */}

        <div className="flex-1 flex flex-col h-full relative z-10 p-2 md:p-4">
          {/* Tab Content Routing */}
          {activeTab === 'chat' && (
            <div className="flex h-full gap-2 md:gap-4">
              {/* Chat Panel (Full width on mobile, 1/3 on XL) */}
              <div className="w-full xl:w-1/3 h-full flex flex-col glass rounded-2xl md:rounded-3xl overflow-hidden relative">
                {/* Background Effect */}
                <div className="absolute top-0 w-full h-32 bg-gradient-to-b from-blue-900/20 to-transparent pointer-events-none" />
                <ChatInterface
                  onStateChange={(talking, emo, thinking) => {
                    setIsTalking(talking);
                    setEmotion(emo);
                    if (typeof thinking === "boolean") {
                      setIsThinking(thinking);
                    }
                  }}
                  onAgentStateChange={(state) => setAgentState(state)}
                  agentMode={agentMode} // Pass mode to chat
                />
              </div>

              {/* Avatar Panel (Right, Grows to fill space) */}
              <div className="hidden xl:flex flex-1 h-full flex-col gap-2">
                <div className="flex-1 rounded-3xl overflow-hidden glass-panel">
                  <AvatarView isTalking={isTalking} emotion={emotion} isThinking={isThinking} stateTag={agentState} />
                </div>
                <div className="h-[40%] min-h-[240px] rounded-3xl overflow-hidden glass-panel">
                  {agentMode === 'stream' ? (
                    <LivestreamDashboard />
                  ) : (
                    <ActionPanel threadId="default_thread" />
                  )}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'memories' && (
            <div className="flex-1 glass rounded-2xl md:rounded-3xl p-4 md:p-8 overflow-y-auto">
              <MemoryExplorer />
            </div>
          )}

          {/* profile tab disabled */}

          {activeTab === 'settings' && (
            <div className="flex-1 glass rounded-2xl md:rounded-3xl p-4 md:p-8 overflow-y-auto">
              <SettingsPanel currentMode={agentMode} onModeChange={handleModeChange} />
            </div>
          )}

          {activeTab === 'stats' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <StatsPanel />
            </div>
          )}

          {activeTab === 'action_issues' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <ActionIssuesPanel threadId="default_thread" />
            </div>
          )}

          {activeTab === 'draw_lab' && (
            <div className="flex-1 glass rounded-3xl overflow-hidden">
              <DrawLab />
            </div>
          )}

          {activeTab !== 'chat' && activeTab !== 'memories' && activeTab !== 'settings' && activeTab !== 'stats' && activeTab !== 'action_issues' && activeTab !== 'draw_lab' && (
            <div className="flex-1 glass rounded-2xl md:rounded-3xl p-4 md:p-8 flex items-center justify-center">
              <div className="text-center">
                <h2 className="text-3xl font-bold mb-2">準備中</h2>
                <p className="text-gray-500">{activeTab} モジュールは現在開発中です。</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </main>
  );
}

"use client";
import React, { useEffect, useState } from "react";
import { AlertTriangle, RefreshCw } from "lucide-react";
import { API_URL } from "@/lib/api";

type LegacyPendingIssue = {
  id?: string;
  action_type?: string;
  status?: string;
  reason?: string;
  message_id?: string;
  created_at?: number;
  updated_at?: number;
};

interface ActionIssuesPanelProps {
  threadId?: string;
}

const statusLabel = (status?: string) => {
  switch ((status || "").toUpperCase()) {
    case "REJECTED":
      return "却下";
    case "ERROR":
      return "失敗";
    case "ARCHIVED":
      return "アーカイブ";
    default:
      return status || "不明";
  }
};

export default function ActionIssuesPanel({ threadId = "default_thread" }: ActionIssuesPanelProps) {
  const [items, setItems] = useState<LegacyPendingIssue[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
  const [showArchived, setShowArchived] = useState(false);

  const fetchIssues = async () => {
    setLoading(true);
    setError(null);
    try {
      const statusParam = showArchived ? "ERROR,REJECTED,ARCHIVED" : "ERROR,REJECTED";
      const res = await fetch(
        `${API_URL}/actions/pending?thread_id=${encodeURIComponent(threadId)}&status=${statusParam}&limit=100`,
        { cache: "no-store" }
      );
      if (!res.ok) throw new Error(`issues fetch failed: ${res.status}`);
      const data = await res.json();
      setItems(Array.isArray(data?.items) ? data.items : []);
    } catch (e) {
      console.error(e);
      setError("失敗/却下の取得に失敗しました");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchIssues();
  }, [threadId, showArchived]);

  const deleteIssue = async (id?: string) => {
    if (!id) return;
    const ok = window.confirm("この失敗/却下アクションを削除しますか？");
    if (!ok) return;
    setPendingDeleteId(id);
    try {
      const res = await fetch(`${API_URL}/actions/${encodeURIComponent(id)}/archive`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ reason: "ui_delete" }),
      });
      if (!res.ok && res.status !== 404) {
        throw new Error(`delete failed: ${res.status}`);
      }
      setItems((prev) => prev.filter((item) => item.id !== id));
    } catch (e) {
      console.error(e);
      setError("削除に失敗しました");
    } finally {
      setPendingDeleteId(null);
    }
  };

  return (
    <div className="h-full w-full p-4 md:p-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-sm font-semibold text-white/90">
          <AlertTriangle size={16} className="text-rose-300" />
          失敗/却下アクション
        </div>
        <div className="flex items-center gap-3">
          <label className="flex items-center gap-2 text-[11px] text-gray-300">
            <input
              type="checkbox"
              checked={showArchived}
              onChange={(e) => setShowArchived(e.target.checked)}
              className="h-3 w-3 accent-rose-400"
            />
            アーカイブも表示
          </label>
          <button
            onClick={fetchIssues}
            className="flex items-center gap-1 text-xs text-gray-300 hover:text-white"
            title="再読み込み"
          >
            <RefreshCw size={14} />
            更新
          </button>
        </div>
      </div>

      <div className="mt-1 text-[11px] text-gray-400">件数: {items.length}</div>
      {error && <div className="mt-2 text-xs text-red-300">{error}</div>}

      <div className="mt-4 space-y-3">
        {items.map((item) => (
          <div key={item.id} className="rounded-xl border border-rose-500/30 bg-rose-900/20 p-3">
            <div className="flex items-center justify-between text-xs text-rose-100">
              <span className="flex items-center gap-1">
                <AlertTriangle size={12} />
                {statusLabel(item.status)}
              </span>
              <span className="text-rose-200/80">{item.action_type || item.id}</span>
            </div>
            <div className="mt-1 text-[11px] text-rose-100/90">理由: {item.reason || "理由なし"}</div>
            {item.created_at && (
              <div className="mt-1 text-[10px] text-rose-200/70">
                登録: {new Date(item.created_at * 1000).toLocaleString()}
              </div>
            )}
            <div className="mt-2">
              <button
                onClick={() => deleteIssue(item.id)}
                disabled={pendingDeleteId === item.id}
                className="rounded-md border border-rose-400/40 bg-rose-500/20 px-2 py-1 text-[10px] text-rose-100 hover:bg-rose-500/30 disabled:opacity-60"
              >
                削除
              </button>
            </div>
          </div>
        ))}
        {!loading && items.length === 0 && (
          <div className="text-xs text-gray-400">失敗・却下の履歴はありません。</div>
        )}
        {loading && (
          <div className="text-xs text-gray-400">読み込み中…</div>
        )}
      </div>
    </div>
  );
}

"use client";
import React, { useEffect, useMemo, useState } from "react";
import { API_URL } from "@/lib/api";
import { Check, X, RefreshCw } from "lucide-react";

type Phase5Pending = {
  kind?: string;
  text?: string;
  risk?: string;
  review_token?: string;
  pending_id?: string;
  action_id?: string;
  name?: string;
  description?: string;
  category?: string;
  risk_level?: string;
  risk_score?: number;
  payload?: Record<string, any>;
  decision?: {
    reason?: string;
    requires_confirmation?: boolean;
    suggested_depth?: number | null;
  };
  requested_at?: number;
};

type Phase5Result = {
  action_id?: string;
  status?: string;
  result?: any;
  approved_by?: string;
  ts?: number;
  source?: string;
};

interface ActionPanelProps {
  threadId?: string;
}

const riskBadge = (risk?: string) => {
  const key = (risk || "").toUpperCase();
  switch (key) {
    case "SAFE":
      return "border-emerald-400/30 text-emerald-200 bg-emerald-900/20";
    case "LOW":
      return "border-sky-400/30 text-sky-200 bg-sky-900/20";
    case "MEDIUM":
    case "MED":
      return "border-amber-400/30 text-amber-200 bg-amber-900/20";
    case "HIGH":
      return "border-orange-400/30 text-orange-200 bg-orange-900/20";
    case "CRITICAL":
      return "border-red-400/40 text-red-200 bg-red-900/30";
    default:
      return "border-white/10 text-gray-300 bg-white/5";
  }
};

export default function ActionPanel({ threadId = "default_thread" }: ActionPanelProps) {
  const [pending, setPending] = useState<Phase5Pending[]>([]);
  const [reviewToken, setReviewToken] = useState<string | null>(null);
  const [results, setResults] = useState<Phase5Result[]>([]);
  const [historyResults, setHistoryResults] = useState<Phase5Result[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [reasonById, setReasonById] = useState<Record<string, string>>({});
  const [resultTab, setResultTab] = useState<"state" | "history">("state");

  const fetchPending = async () => {
    try {
      const res = await fetch(
        `${API_URL}/actions/phase5/pending?thread_id=${encodeURIComponent(threadId)}`,
        { cache: "no-store" }
      );
      if (!res.ok) throw new Error(`pending fetch failed: ${res.status}`);
      const data = await res.json();
      const token = typeof data?.review_token === "string" ? data.review_token : null;
      setReviewToken(token);
      const items = Array.isArray(data?.items) ? data.items : [];
      const normalized = items.map((item: Phase5Pending) => {
        if ((item?.kind || "").toLowerCase() === "say") {
          return { ...item, review_token: item.review_token || token || undefined };
        }
        return item;
      });
      setPending(normalized);
    } catch (e) {
      console.error(e);
      setError("pending_actions の取得に失敗しました");
    }
  };

  const fetchResults = async () => {
    try {
      const res = await fetch(
        `${API_URL}/actions/phase5/results?thread_id=${encodeURIComponent(threadId)}`,
        { cache: "no-store" }
      );
      if (!res.ok) throw new Error(`results fetch failed: ${res.status}`);
      const data = await res.json();
      setResults(Array.isArray(data?.items) ? data.items : []);
    } catch (e) {
      console.error(e);
      setError("action_results の取得に失敗しました");
    }
  };

  const fetchHistoryResults = async () => {
    try {
      const res = await fetch(
        `${API_URL}/actions/phase5/results/history?thread_id=${encodeURIComponent(threadId)}&limit=50`,
        { cache: "no-store" }
      );
      if (!res.ok) throw new Error(`results history fetch failed: ${res.status}`);
      const data = await res.json();
      setHistoryResults(Array.isArray(data?.items) ? data.items : []);
    } catch (e) {
      console.error(e);
      setError("action_results 履歴の取得に失敗しました");
    }
  };

  const refreshAll = async () => {
    setLoading(true);
    setError(null);
    await Promise.all([fetchPending(), fetchResults(), fetchHistoryResults()]);
    setLoading(false);
  };

  useEffect(() => {
    refreshAll();
  }, [threadId]);

  useEffect(() => {
    const handler = (ev: Event) => {
      const detail = (ev as CustomEvent).detail || {};
      if (!detail?.name) return;
      // action_proposed / action_approved / action_blocked
      refreshAll();
    };
    if (typeof window !== "undefined") {
      window.addEventListener("phase5-action-event", handler as EventListener);
      return () => window.removeEventListener("phase5-action-event", handler as EventListener);
    }
  }, []);

  const updateReason = (pendingId: string | undefined, value: string) => {
    if (!pendingId) return;
    setReasonById((prev) => ({ ...prev, [pendingId]: value }));
  };

  const postDecision = async (item: Phase5Pending, decision: "approve" | "reject") => {
    const kind = (item.kind || "").toLowerCase();
    try {
      let res: Response;
      if (kind === "say") {
        const token = item.review_token || reviewToken;
        if (!token) {
          setError("review_token が見つからないため、承認/拒否できません");
          return;
        }
        res = await fetch(`${API_URL}/review/${decision}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ thread_id: threadId, review_token: token }),
        });
      } else {
        const actionId = item.action_id;
        const pendingId = item.pending_id;
        if (!actionId || !pendingId) {
          setError("action_id または pending_id が不足しているため、承認/拒否できません");
          return;
        }
        const reason = reasonById[pendingId] || "";
        res = await fetch(`${API_URL}/actions/phase5/${encodeURIComponent(actionId)}/${decision}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ thread_id: threadId, pending_id: pendingId, reason }),
        });
      }
      if (!res.ok) throw new Error(`${decision} failed: ${res.status}`);
      await refreshAll();
    } catch (e) {
      console.error(e);
      setError(`アクションの${decision}に失敗しました`);
    }
  };

  const pendingCount = pending.length;
  const recentResults = useMemo(() => results.slice(-6).reverse(), [results]);
  const recentHistoryResults = useMemo(() => historyResults.slice(0, 10), [historyResults]);

  return (
    <div className="h-full w-full p-3">
      <div className="flex items-center justify-between">
        <div className="text-sm font-semibold text-white/90">Phase5 Actions</div>
        <button
          onClick={refreshAll}
          className="flex items-center gap-1 text-xs text-gray-300 hover:text-white"
          title="再読み込み"
        >
          <RefreshCw size={14} />
          更新
        </button>
      </div>
      <div className="mt-1 text-[11px] text-gray-400">pending: {pendingCount}</div>
      {error && <div className="mt-2 text-xs text-red-300">{error}</div>}

      <div className="mt-3 space-y-3">
        {pending.map((item, idx) => {
          const pendingId = item.pending_id;
          const actionId = item.action_id;
          const decision = item.decision || {};
          const isSayPreview = (item.kind || "").toLowerCase() === "say";
          const title = isSayPreview ? "Speech Preview" : item.name || actionId;
          const risk = item.risk_level || item.risk;
          const itemKey =
            pendingId ||
            `${actionId || item.kind || "unknown-action"}:${item.requested_at || "no-ts"}:${item.name || "no-name"}:${idx}`;
          return (
            <div key={itemKey} className="rounded-xl border border-white/10 bg-white/5 p-3">
              <div className="flex items-center justify-between gap-2">
                <div className="text-sm text-white/90">{title}</div>
                <span className={`text-[10px] px-2 py-0.5 rounded-full border ${riskBadge(risk)}`}>
                  {risk || "UNKNOWN"}
                </span>
              </div>
              {item.description && (
                <div className="mt-1 text-xs text-gray-400">{item.description}</div>
              )}
              {isSayPreview && item.text && (
                <div className="mt-2 text-xs text-gray-300 line-clamp-3">{item.text}</div>
              )}
              {decision.reason && (
                <div className="mt-2 text-[11px] text-amber-200/80">理由: {decision.reason}</div>
              )}
              {decision.requires_confirmation && (
                <div className="mt-1 text-[11px] text-amber-200/70">要確認</div>
              )}
              <div className="mt-2 flex items-center gap-2">
                {!isSayPreview && (
                  <input
                    type="text"
                    value={pendingId ? (reasonById[pendingId] || "") : ""}
                    onChange={(e) => updateReason(pendingId, e.target.value)}
                    placeholder="理由（任意）"
                    className="flex-1 rounded-lg bg-black/30 px-2 py-1 text-xs text-gray-100 placeholder:text-gray-500"
                  />
                )}
                <button
                  onClick={() => postDecision(item, "approve")}
                  className="flex items-center gap-1 rounded-lg border border-emerald-500/40 bg-emerald-500/20 px-2 py-1 text-xs text-emerald-100"
                >
                  <Check size={12} /> 承認
                </button>
                <button
                  onClick={() => postDecision(item, "reject")}
                  className="flex items-center gap-1 rounded-lg border border-red-500/40 bg-red-500/20 px-2 py-1 text-xs text-red-100"
                >
                  <X size={12} /> 拒否
                </button>
              </div>
            </div>
          );
        })}
        {!loading && pending.length === 0 && (
          <div className="text-xs text-gray-400">保留中のアクションはありません。</div>
        )}
      </div>

      <div className="mt-4 border-t border-white/10 pt-3">
        <div className="flex items-center justify-between">
          <div className="text-xs text-gray-300">実行結果</div>
          <div className="flex items-center gap-2 text-[10px]">
            <button
              onClick={() => setResultTab("state")}
              className={`rounded-full border px-2 py-0.5 ${
                resultTab === "state"
                  ? "border-sky-400/50 text-sky-200 bg-sky-500/20"
                  : "border-white/10 text-gray-400"
              }`}
            >
              最新（state）
            </button>
            <button
              onClick={() => setResultTab("history")}
              className={`rounded-full border px-2 py-0.5 ${
                resultTab === "history"
                  ? "border-rose-400/50 text-rose-200 bg-rose-500/20"
                  : "border-white/10 text-gray-400"
              }`}
            >
              履歴（永続）
            </button>
          </div>
        </div>
        <div className="mt-2 space-y-2">
          {(resultTab === "state" ? recentResults : recentHistoryResults).map((r, idx) => (
            <div key={`${r.action_id}-${idx}`} className="rounded-lg border border-white/10 bg-white/5 px-2 py-2">
              <div className="flex items-center justify-between text-xs">
                <span className="text-gray-200">{r.action_id}</span>
                <span className={`text-[10px] ${r.status === "success" ? "text-emerald-200" : "text-red-200"}`}>
                  {r.status}
                </span>
              </div>
              {r.source && (
                <div className="mt-1 text-[10px] text-gray-500">source: {r.source}</div>
              )}
              {r.result?.message && (
                <div className="mt-1 text-[11px] text-gray-400">{r.result.message}</div>
              )}
            </div>
          ))}
          {resultTab === "state" && recentResults.length === 0 && (
            <div className="text-xs text-gray-400">まだ実行結果はありません。</div>
          )}
          {resultTab === "history" && recentHistoryResults.length === 0 && (
            <div className="text-xs text-gray-400">履歴はまだありません。</div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";
import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { VRMLoaderPlugin, VRMUtils, VRM } from '@pixiv/three-vrm';

interface AvatarProps {
    isTalking: boolean;
    emotion: string;
    isThinking?: boolean;
    stateTag?: string;
}

export default function AvatarView({ isTalking, emotion, isThinking = false, stateTag = "" }: AvatarProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const vrmRef = useRef<VRM | null>(null);
    const clockRef = useRef(new THREE.Clock());
    const emotionRef = useRef<string>(emotion);
    const stateRef = useRef<string>(stateTag);
    const thinkingRef = useRef<boolean>(isThinking);
    const noiseRef = useRef({
        currentFreq: 1.0,
        targetFreq: 1.0,
        nextUpdateAt: 0,
        phase: 0,
        seed: 42.1337,
    });

    useEffect(() => {
        if (!containerRef.current) return;

        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x0f0f12);

        const camera = new THREE.PerspectiveCamera(30, containerRef.current.clientWidth / containerRef.current.clientHeight, 0.1, 20.0);
        camera.position.set(0.0, 1.3, 1.4);

        const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
        renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
        renderer.setPixelRatio(window.devicePixelRatio);
        containerRef.current.appendChild(renderer.domElement);

        const light = new THREE.DirectionalLight(0xffffff);
        light.position.set(1.0, 1.0, 1.0).normalize();
        scene.add(light);
        const ambient = new THREE.AmbientLight(0x404040);
        scene.add(ambient);

        const loader = new GLTFLoader();
        loader.register((parser) => new VRMLoaderPlugin(parser));

        loader.load(
            '/avatar.vrm',
            (gltf) => {
                const vrm = gltf.userData.vrm;
                VRMUtils.removeUnnecessaryVertices(gltf.scene);
                VRMUtils.combineSkeletons(gltf.scene);
                vrm.scene.rotation.y = 0;
                scene.add(vrm.scene);
                vrmRef.current = vrm;
            },
            (progress) => console.log('Loading VRM...', 100.0 * (progress.loaded / progress.total), '%'),
            (error) => console.error("VRM Load Failed:", error)
        );

        const getMotionParams = () => {
            const state = (stateRef.current || "").toLowerCase();
            const emotionTag = (emotionRef.current || "").toLowerCase();
            const tag = state || emotionTag;
            const pondering = Boolean(thinkingRef.current) || tag === "pondering";

            let amplitude = 0.0045;
            let baseFrequency = 0.55;
            let jitter = 0.18;
            let damping = 0.08;

            if (tag === "consent") {
                amplitude = 0.0030;
                damping = 0.14;
                jitter = 0.08;
            }

            if (tag === "dissonance") {
                amplitude = 0.0060;
                baseFrequency = 0.8;
                jitter = 0.35;
                damping = 0.05;
            }

            if (pondering) {
                baseFrequency = 0.5;
                jitter = 0.12;
            }

            return { amplitude, baseFrequency, jitter, damping, pondering };
        };

        const animate = () => {
            requestAnimationFrame(animate);
            const delta = clockRef.current.getDelta();
            const vrm = vrmRef.current;

            if (vrm) {
                const humanoid = vrm.humanoid;
                if (humanoid) {
                    const leftArm = humanoid.getNormalizedBoneNode('leftUpperArm');
                    const rightArm = humanoid.getNormalizedBoneNode('rightUpperArm');
                    if (leftArm) leftArm.rotation.z = -1.3;
                    if (rightArm) rightArm.rotation.z = 1.3;
                }

                vrm.update(delta);

                const t = clockRef.current.elapsedTime;
                const { amplitude, baseFrequency, jitter, damping, pondering } = getMotionParams();

                if (t >= noiseRef.current.nextUpdateAt) {
                    const pseudo = Math.sin(t * 1.731 + noiseRef.current.seed) * 0.5 + 0.5;
                    noiseRef.current.targetFreq = Math.max(0.4, baseFrequency + (pseudo - 0.5) * jitter * 2.0);
                    const interval = 1.5 + (pseudo * 1.5); // 1.5〜3.0秒
                    noiseRef.current.nextUpdateAt = t + interval;
                }

                noiseRef.current.currentFreq += (noiseRef.current.targetFreq - noiseRef.current.currentFreq) * damping;
                noiseRef.current.phase += noiseRef.current.currentFreq * delta * Math.PI * 2.0;

                let amp = amplitude;
                if (pondering) {
                    const slowT = t * (Math.PI * 2.0) * 0.2; // 0.2Hz
                    const wave = 0.5 + 0.5 * Math.sin(slowT);
                    amp = amplitude * (0.3 + 0.7 * wave);
                }

                vrm.scene.rotation.z = Math.sin(noiseRef.current.phase) * amp;

                if (humanoid) {
                    const head = humanoid.getNormalizedBoneNode('head');
                    if (head) {
                        if (thinkingRef.current) {
                            head.rotation.y = Math.sin(t * 0.7) * 0.15;
                            head.rotation.x = -0.06 + Math.sin(t * 0.9) * 0.03;
                        } else {
                            head.rotation.x = 0;
                            head.rotation.y = 0;
                        }
                    }
                }

                if (Math.random() < 0.005) {
                    vrm.expressionManager?.setValue('blink', 1.0);
                    setTimeout(() => vrm.expressionManager?.setValue('blink', 0.0), 100);
                }
            }

            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            camera.aspect = containerRef.current.clientWidth / containerRef.current.clientHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('resize', handleResize);
            renderer.dispose();
            if (containerRef.current?.contains(renderer.domElement)) {
                containerRef.current.removeChild(renderer.domElement);
            }
        };
    }, []);

    useEffect(() => {
        emotionRef.current = emotion;
    }, [emotion]);

    useEffect(() => {
        stateRef.current = stateTag;
    }, [stateTag]);

    useEffect(() => {
        thinkingRef.current = isThinking;
    }, [isThinking]);

    useEffect(() => {
        const vrm = vrmRef.current;
        if (!vrm || !vrm.expressionManager) return;

        const list = vrm.expressionManager.expressions;
        list.forEach(e => {
            if (e.expressionName !== 'blink' && e.expressionName !== 'aa') {
                vrm.expressionManager?.setValue(e.expressionName, 0);
            }
        });

        let targetExpression = 'neutral';
        if (emotion === 'happy') targetExpression = 'happy';
        if (emotion === 'sad') targetExpression = 'sad';
        if (emotion === 'angry') targetExpression = 'angry';
        if (emotion === 'surprised') targetExpression = 'surprised';
        if (emotion === 'consent') targetExpression = 'neutral';
        if (emotion === 'dissonance') targetExpression = 'neutral';
        if (emotion === 'pondering') targetExpression = 'neutral';

        if (vrm.expressionManager.getExpression(targetExpression)) {
            vrm.expressionManager.setValue(targetExpression, 1.0);
        } else {
            if (emotion === 'happy') vrm.expressionManager.setValue('joy', 1.0);
            else vrm.expressionManager.setValue('neutral', 1.0);
        }
    }, [emotion]);

    useEffect(() => {
        let frameId: number;
        const lipLoop = () => {
            const vrm = vrmRef.current;
            if (vrm && vrm.expressionManager) {
                if (isTalking) {
                    const v = 0.2 + 0.4 * Math.sin(Date.now() / 60);
                    vrm.expressionManager.setValue('aa', v);
                } else {
                    vrm.expressionManager.setValue('aa', 0);
                }
            }
            frameId = requestAnimationFrame(lipLoop);
        };
        lipLoop();
        return () => cancelAnimationFrame(frameId);
    }, [isTalking]);

    return (
        <div className="w-full h-full glass-panel relative overflow-hidden rounded-2xl">
            <div ref={containerRef} className="w-full h-full" />
        </div>
    );
}

"use client";
import React, { useState, useRef, useEffect } from 'react';
import { Send, Mic, Image as ImageIcon, StopCircle } from 'lucide-react';
import { API_URL, ChatMessage, getStaticUrl } from '@/lib/api';
import { motion, AnimatePresence } from 'framer-motion';

interface ChatInterfaceProps {
    onStateChange: (isTalking: boolean, emotion: string, isThinking?: boolean) => void;
    onAgentStateChange?: (state: string) => void;
    agentMode: string;
}

interface ReviewRequestPayload {
    review_token: string;
    hold_kind?: string;
    preview_text?: string;
    reason_codes?: string[];
}

export default function ChatInterface({ onStateChange, onAgentStateChange, agentMode }: ChatInterfaceProps) {
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [input, setInput] = useState("");
    const [isLoading, setIsLoading] = useState(false);
    const [threadId, setThreadId] = useState<string>("");
    const [currentEmotion, setCurrentEmotion] = useState("neutral");
    const [isThinking, setIsThinking] = useState(false);
    const [connectionState, setConnectionState] = useState<"ok" | "stale">("ok");
    const [thinkingHint, setThinkingHint] = useState<any | null>(null);
    const [reviewRequest, setReviewRequest] = useState<ReviewRequestPayload | null>(null);
    const [pendingActions, setPendingActions] = useState<any[]>([]);
    const [pendingMeta, setPendingMeta] = useState<{ pending_count: number; dissonance_delta: number } | null>(null);
    const [pendingLoading, setPendingLoading] = useState(false);
    const [pendingError, setPendingError] = useState<string | null>(null);
    const [pendingReasonById, setPendingReasonById] = useState<Record<string, string>>({});
    const [latestCommitLog, setLatestCommitLog] = useState<any | null>(null);

    // Vision State
    const [selectedImage, setSelectedImage] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const AFFECT_REGEX = /\[(happy|sad|angry|relaxed|surprised|shy|sigh|neutral|consent|dissonance)\]/g;
    const scrollRef = useRef<HTMLDivElement>(null);

    // Audio Playback Queue
    const audioQueueRef = useRef<string[]>([]);
    const isPlayingRef = useRef(false);
    const audioRef = useRef<HTMLAudioElement | null>(null);

    // Stream Refs
    const aiMsgIdRef = useRef<string | null>(null);
    const aiTextRef = useRef<string>("");
    const isStreamingRef = useRef(false);
    const isThinkingRef = useRef(false);
    const lastEventAtRef = useRef<number>(0);
    const activeStreamIdRef = useRef<number>(0);
    const sseStreamIdRef = useRef<string | null>(null);
    const abortControllerRef = useRef<AbortController | null>(null);
    const currentStateRef = useRef<string>("");
    const ttsEsRef = useRef<EventSource | null>(null);
    const voiceWsRef = useRef<WebSocket | null>(null);
    const mediaRecorderRef = useRef<MediaRecorder | null>(null);
    const mediaStreamRef = useRef<MediaStream | null>(null);
    const voiceChunkSeqRef = useRef<number>(0);
    const voiceSessionIdRef = useRef<string>("");
    const micVadRef = useRef<any>(null);
    const vadStreamRef = useRef<MediaStream | null>(null);
    const vadMaxTurnTimerRef = useRef<number | null>(null);
    const vadAwaitingFinalRef = useRef<boolean>(false);
    const vadSpeechActiveRef = useRef<boolean>(false);
    const voiceCurrentUtteranceIdRef = useRef<string>("");
    const voiceUtteranceCounterRef = useRef<number>(0);
    const speechSendingRef = useRef<boolean>(false);
    const preRollChunksRef = useRef<Blob[]>([]);
    const webmHeaderBlobRef = useRef<Blob | null>(null);
    const pendingVoiceSendRef = useRef<string | null>(null);
    const lastAutoSentTextRef = useRef<string>("");
    const lastAutoSentAtRef = useRef<number>(0);
    const tryAutoSendRef = useRef<(text: string) => void>(() => {});
    const sendMessageRef = useRef<(text?: string) => Promise<void>>(async () => {});
    const restartRecorderRef = useRef<() => void>(() => {});

    const [voiceModeEnabled, setVoiceModeEnabled] = useState(false);
    const [voiceWsState, setVoiceWsState] = useState<"idle" | "connecting" | "connected" | "error">("idle");
    const [voiceError, setVoiceError] = useState<string | null>(null);
    const [sttPreview, setSttPreview] = useState<string>("");

    const syncThinking = (next: boolean) => {
        isThinkingRef.current = next;
        setIsThinking(next);
        onStateChange(isPlayingRef.current, currentEmotion, next);
    };

    const blobToBase64 = (blob: Blob): Promise<string> =>
        new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onloadend = () => {
                const result = String(reader.result || "");
                const payload = result.includes(",") ? result.split(",")[1] : "";
                resolve(payload);
            };
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });

    const buildVoiceWsUrl = (sessionId: string, clientId: string) => {
        const wsScheme = window.location.protocol === "https:" ? "wss" : "ws";
        const wsBase = API_URL.startsWith("http")
            ? API_URL.replace(/^http/i, "ws")
            : `${wsScheme}://${window.location.host}${API_URL}`;
        const qs = `session_id=${encodeURIComponent(sessionId)}&client_id=${encodeURIComponent(clientId)}`;
        return `${wsBase}/voice/ws?${qs}`;
    };

    const cleanupVoiceRuntime = () => {
        const rec = mediaRecorderRef.current;
        if (rec && rec.state !== "inactive") {
            rec.stop();
        }
        mediaRecorderRef.current = null;

        const stream = mediaStreamRef.current;
        if (stream) {
            stream.getTracks().forEach((t) => t.stop());
        }
        mediaStreamRef.current = null;

        const ws = voiceWsRef.current;
        if (ws) {
            try {
                ws.close();
            } catch { }
        }
        voiceWsRef.current = null;

        const vad = micVadRef.current;
        if (vad) {
            vad.destroy().catch(() => { });
            micVadRef.current = null;
        }
        const vs = vadStreamRef.current;
        if (vs) {
            vs.getTracks().forEach((t: MediaStreamTrack) => t.stop());
            vadStreamRef.current = null;
        }
        if (vadMaxTurnTimerRef.current != null) {
            window.clearTimeout(vadMaxTurnTimerRef.current);
            vadMaxTurnTimerRef.current = null;
        }
        vadAwaitingFinalRef.current = false;
        vadSpeechActiveRef.current = false;
        voiceCurrentUtteranceIdRef.current = "";
        speechSendingRef.current = false;
        preRollChunksRef.current = [];
    };

    const interruptAudioPlayback = () => {
        const audio = audioRef.current;
        if (audio) {
            try {
                audio.pause();
                audio.currentTime = 0;
            } catch { }
        }
        audioQueueRef.current = [];
        isPlayingRef.current = false;
        onStateChange(false, currentEmotion, isThinkingRef.current);
        // barge-in: TTS停止後にVADを再開
        micVadRef.current?.start().catch(() => {});
    };

    const toNum = (v: string | undefined, fallback: number) => {
        const n = Number(v);
        return Number.isFinite(n) ? n : fallback;
    };
    const VAD_MIN_CHUNKS = toNum(process.env.NEXT_PUBLIC_VAD_MIN_CHUNKS, 3);
    const VAD_MAX_TURN_MS = toNum(process.env.NEXT_PUBLIC_VAD_MAX_TURN_MS, 6000);
    const VAD_POSITIVE_THRESHOLD = toNum(process.env.NEXT_PUBLIC_VAD_POSITIVE_THRESHOLD, 0.5);
    const VAD_NEGATIVE_THRESHOLD = toNum(process.env.NEXT_PUBLIC_VAD_NEGATIVE_THRESHOLD, 0.35);
    const VAD_REDEMPTION_MS = toNum(process.env.NEXT_PUBLIC_VAD_REDEMPTION_MS, 700);
    const VAD_MIN_SPEECH_MS = toNum(process.env.NEXT_PUBLIC_VAD_MIN_SPEECH_MS, 250);
    const VAD_PRE_SPEECH_PAD_MS = toNum(process.env.NEXT_PUBLIC_VAD_PRE_SPEECH_PAD_MS, 300);
    const VOICE_CHUNK_MS = toNum(process.env.NEXT_PUBLIC_VOICE_CHUNK_MS, 500);
    const VAD_PRE_ROLL_MS = toNum(process.env.NEXT_PUBLIC_VAD_PRE_ROLL_MS, 450);
    const VAD_PRE_ROLL_CHUNKS = Math.max(1, Math.ceil(VAD_PRE_ROLL_MS / Math.max(100, VOICE_CHUNK_MS)));
    const AUDIO_ECHO_CANCELLATION = String(process.env.NEXT_PUBLIC_AUDIO_ECHO_CANCELLATION ?? "1") !== "0";
    const AUDIO_NOISE_SUPPRESSION = String(process.env.NEXT_PUBLIC_AUDIO_NOISE_SUPPRESSION ?? "0") === "1";
    const AUDIO_AUTO_GAIN = String(process.env.NEXT_PUBLIC_AUDIO_AUTO_GAIN ?? "1") !== "0";

    const sendVoiceTurnEnd = (
        ws: WebSocket | null,
        mimeType: string,
        meta?: { source?: string; rms?: number; speechMs?: number; chunks?: number; utteranceId?: string }
    ) => {
        if (!ws || ws.readyState !== WebSocket.OPEN) return;
        try {
            ws.send(
                JSON.stringify({
                    type: "voice_turn_end",
                    utterance_id: meta?.utteranceId || voiceCurrentUtteranceIdRef.current || "default",
                    mime_type: mimeType || "audio/webm",
                    source: meta?.source || "manual",
                    rms: meta?.rms,
                    speech_ms: meta?.speechMs,
                    chunks: meta?.chunks,
                })
            );
            vadAwaitingFinalRef.current = true;
        } catch { }
    };

    const nextUtteranceId = () => {
        voiceUtteranceCounterRef.current += 1;
        return `utt-${Date.now()}-${voiceUtteranceCounterRef.current}`;
    };

    const sendChunkBlob = async (
        blob: Blob,
        ws: WebSocket | null,
        sessionId: string,
        fallbackMime: string,
        utteranceId: string
    ) => {
        if (!blob || blob.size <= 0) return;
        if (!ws || ws.readyState !== WebSocket.OPEN) return;
        if (!utteranceId) return;
        const seq = ++voiceChunkSeqRef.current;
        try {
            const chunkB64 = await blobToBase64(blob);
            ws.send(
                JSON.stringify({
                    type: "voice_chunk",
                    seq,
                    session_id: sessionId,
                    utterance_id: utteranceId,
                    mime_type: blob.type || fallbackMime || "audio/webm",
                    payload_b64: chunkB64,
                    size: blob.size,
                })
            );
        } catch (e) {
            console.warn("[VOICE] chunk encode failed", e);
        }
    };

    const setupMicVad = async (stream: MediaStream, ws: WebSocket, mimeType: string) => {
        try {
            const { MicVAD } = await import("@ricky0123/vad-web");

            vadAwaitingFinalRef.current = false;
            vadSpeechActiveRef.current = false;

            // vad-web は内部で AudioContext + AudioWorklet を作成する。
            // 同じ MediaStream を共有すると MediaRecorder の録音品質に
            // 干渉するケースがあるため、クローンを渡して隔離する。
            const vadStream = stream.clone();
            vadStreamRef.current = vadStream;
            const micVad = await MicVAD.new({
                getStream: async () => vadStream,
                baseAssetPath: "/vad/",
                onnxWASMBasePath: "/vad/",
                positiveSpeechThreshold: VAD_POSITIVE_THRESHOLD,
                negativeSpeechThreshold: VAD_NEGATIVE_THRESHOLD,
                redemptionMs: VAD_REDEMPTION_MS,
                minSpeechMs: VAD_MIN_SPEECH_MS,
                preSpeechPadMs: VAD_PRE_SPEECH_PAD_MS,

                onSpeechStart: () => {
                    if (vadAwaitingFinalRef.current) return;

                    if (isPlayingRef.current) {
                        interruptAudioPlayback();
                    }

                    vadSpeechActiveRef.current = true;
                    const utteranceId = nextUtteranceId();
                    voiceCurrentUtteranceIdRef.current = utteranceId;
                    speechSendingRef.current = true;
                    voiceChunkSeqRef.current = 0;

                    const sid = voiceSessionIdRef.current;
                    const headerBlob = webmHeaderBlobRef.current;
                    if (headerBlob) {
                        void sendChunkBlob(headerBlob, ws, sid, mimeType, utteranceId);
                    }
                    const preRoll = [...preRollChunksRef.current];
                    preRollChunksRef.current = [];
                    for (const chunk of preRoll) {
                        if (chunk === headerBlob) continue;
                        void sendChunkBlob(chunk, ws, sid, mimeType, utteranceId);
                    }

                    if (vadMaxTurnTimerRef.current != null) {
                        window.clearTimeout(vadMaxTurnTimerRef.current);
                    }
                    vadMaxTurnTimerRef.current = window.setTimeout(() => {
                        if (!vadSpeechActiveRef.current) return;
                        speechSendingRef.current = false;
                        vadSpeechActiveRef.current = false;
                        vadAwaitingFinalRef.current = true;
                        console.log("[VOICE][VAD] max_turn", { chunks: voiceChunkSeqRef.current });
                        sendVoiceTurnEnd(ws, mimeType, {
                            source: "vad_max_turn",
                            utteranceId: voiceCurrentUtteranceIdRef.current || undefined,
                            chunks: voiceChunkSeqRef.current,
                        });
                    }, VAD_MAX_TURN_MS);

                    console.log("[VOICE][VAD] speech_start (silero)");
                },

                onSpeechEnd: (_audio: Float32Array) => {
                    if (!vadSpeechActiveRef.current) return;

                    if (vadMaxTurnTimerRef.current != null) {
                        window.clearTimeout(vadMaxTurnTimerRef.current);
                        vadMaxTurnTimerRef.current = null;
                    }

                    if (voiceChunkSeqRef.current < VAD_MIN_CHUNKS) {
                        console.log("[VOICE][VAD] speech too short, ignoring", { chunks: voiceChunkSeqRef.current });
                        vadSpeechActiveRef.current = false;
                        speechSendingRef.current = false;
                        voiceCurrentUtteranceIdRef.current = "";
                        return;
                    }

                    // speechSending を先に切ってから turn_end を送る。
                    // レコーダーは止めない — stt_final で初めてリスタートする。
                    // こうすると最終チャンク（発話末尾）がサーバーに届く。
                    speechSendingRef.current = false;
                    vadSpeechActiveRef.current = false;
                    vadAwaitingFinalRef.current = true;
                    console.log("[VOICE][VAD] speech_end (silero)", { chunks: voiceChunkSeqRef.current });
                    sendVoiceTurnEnd(ws, mimeType, {
                        source: "vad_silence",
                        utteranceId: voiceCurrentUtteranceIdRef.current || undefined,
                        chunks: voiceChunkSeqRef.current,
                    });
                },

                onVADMisfire: () => {
                    console.log("[VOICE][VAD] misfire (speech too short)");
                    if (vadMaxTurnTimerRef.current != null) {
                        window.clearTimeout(vadMaxTurnTimerRef.current);
                        vadMaxTurnTimerRef.current = null;
                    }
                    vadSpeechActiveRef.current = false;
                    speechSendingRef.current = false;
                    voiceCurrentUtteranceIdRef.current = "";
                },
            });

            micVad.start();
            micVadRef.current = micVad;
            console.log("[VOICE][VAD] Silero VAD initialized");
        } catch (e) {
            console.warn("[VOICE] VAD setup failed", e);
        }
    };

    const tryAutoSendVoiceText = (raw: string) => {
        const text = String(raw || "").trim();
        if (!text) return;

        const now = Date.now();
        const prev = lastAutoSentTextRef.current;
        const dt = now - lastAutoSentAtRef.current;
        if (text === prev && dt < 4000) {
            console.log("[VOICE] auto-send dedupe skip", { text, dt });
            return;
        }

        if (isLoading) {
            pendingVoiceSendRef.current = text;
            console.log("[VOICE] auto-send queued", { text, isLoading });
            return;
        }

        console.log("[VOICE] auto-send now", { text });
        lastAutoSentTextRef.current = text;
        lastAutoSentAtRef.current = now;
        sendMessage(text);
    };
    tryAutoSendRef.current = tryAutoSendVoiceText;

    const stopVoiceMode = async () => {
        const ws = voiceWsRef.current;
        if (ws && ws.readyState === WebSocket.OPEN && speechSendingRef.current && voiceChunkSeqRef.current > 0) {
            try {
                sendVoiceTurnEnd(ws, "audio/webm", { source: "manual_stop" });
                await new Promise((r) => setTimeout(r, 120));
            } catch { }
        }
        cleanupVoiceRuntime();
        const sid = voiceSessionIdRef.current;
        voiceSessionIdRef.current = "";
        setVoiceModeEnabled(false);
        setVoiceWsState("idle");
        setSttPreview("");
        if (sid) {
            try {
                await fetch(`${API_URL}/voice/session/stop`, {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ session_id: sid, reason: "client_stop" }),
                });
            } catch (e) {
                console.warn("[VOICE] session stop failed", e);
            }
        }
    };

    const startVoiceMode = async () => {
        if (voiceModeEnabled) return;
        setVoiceError(null);
        setSttPreview("");
        setVoiceWsState("connecting");

        const clientId = `web-${threadId || "default_thread"}`;
        try {
            const startRes = await fetch(`${API_URL}/voice/session/start`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    thread_id: threadId || "default_thread",
                    client_id: clientId,
                }),
            });
            if (!startRes.ok) {
                throw new Error(`voice session start failed: ${startRes.status}`);
            }
            const startData = await startRes.json();
            const sid = String(startData?.session?.session_id || "");
            if (!sid) throw new Error("voice session_id missing");
            voiceSessionIdRef.current = sid;

            const stream = await navigator.mediaDevices.getUserMedia({
                audio: {
                    echoCancellation: AUDIO_ECHO_CANCELLATION,
                    noiseSuppression: AUDIO_NOISE_SUPPRESSION,
                    autoGainControl: AUDIO_AUTO_GAIN,
                    channelCount: 1,
                },
            });
            mediaStreamRef.current = stream;

            const mimeCandidates = ["audio/webm;codecs=opus", "audio/webm", "audio/ogg;codecs=opus"];
            const mimeType = mimeCandidates.find((m) => {
                try {
                    return MediaRecorder.isTypeSupported(m);
                } catch {
                    return false;
                }
            }) || "";

            const ws = new WebSocket(buildVoiceWsUrl(sid, clientId));
            voiceWsRef.current = ws;
            voiceChunkSeqRef.current = 0;
            voiceCurrentUtteranceIdRef.current = "";
            speechSendingRef.current = false;
            preRollChunksRef.current = [];

            ws.onopen = () => {
                setVoiceWsState("connected");
            };
            ws.onclose = () => {
                cleanupVoiceRuntime();
                setVoiceWsState("idle");
                setVoiceModeEnabled(false);
            };
            ws.onerror = () => {
                setVoiceWsState("error");
                setVoiceError("voice ws 接続でエラーが発生しました");
            };
            ws.onmessage = (ev) => {
                try {
                    const data = JSON.parse(ev.data);
                    if (data?.type === "voice_session_state") return;
                    if (data?.type === "stt_partial") {
                        const text = String(data?.text || "");
                        setSttPreview(text);
                        return;
                    }
                    if (data?.type === "stt_final") {
                        const finUtt = String(data?.utterance_id || "");
                        const activeUtt = voiceCurrentUtteranceIdRef.current;
                        if (finUtt && activeUtt && finUtt !== activeUtt) {
                            console.log("[VOICE] stale stt_final ignored", { finUtt, activeUtt });
                            return;
                        }
                        vadAwaitingFinalRef.current = false;
                        speechSendingRef.current = false;
                        voiceCurrentUtteranceIdRef.current = "";
                        // Reset chunk counter so VAD minimum-chunk guard works for next turn
                        voiceChunkSeqRef.current = 0;
                        // Restart MediaRecorder to produce a fresh webm container header
                        // for the next turn (continuation chunks lack the header and
                        // cause ffmpeg decode failures).
                        restartRecorderRef.current();
                        const text = String(data?.text || "");
                        if (text) {
                            setSttPreview(text);
                            // Voice mode: auto-submit recognized text (or queue if currently busy/reviewing)
                            tryAutoSendRef.current(text);
                        } else if (data?.reason) {
                            const reason = String(data.reason || "");
                            // decode失敗は一過性のことが多いので、UIエラー表示は抑制
                            if (reason !== "audio decode failed") {
                                setVoiceError(reason);
                            } else {
                                console.warn("[VOICE] transient decode failure", data);
                            }
                        }
                        return;
                    }
                    if (data?.type === "voice_session_closed") {
                        cleanupVoiceRuntime();
                        setVoiceModeEnabled(false);
                        setVoiceWsState("idle");
                        return;
                    }
                } catch { }
            };

            const makeChunkHandler = () => async (evt: BlobEvent) => {
                if (!evt.data || evt.data.size <= 0) return;
                const socket = voiceWsRef.current;
                if (!socket || socket.readyState !== WebSocket.OPEN) return;
                // Save the very first chunk from this recorder instance as the
                // webm header (EBML + Segment + Tracks).  Pre-roll rotation
                // would discard it, so we keep a separate ref.
                if (!webmHeaderBlobRef.current) {
                    webmHeaderBlobRef.current = evt.data;
                }
                preRollChunksRef.current.push(evt.data);
                if (preRollChunksRef.current.length > VAD_PRE_ROLL_CHUNKS) {
                    preRollChunksRef.current = preRollChunksRef.current.slice(-VAD_PRE_ROLL_CHUNKS);
                }
                if (!speechSendingRef.current) return;
                const utteranceId = voiceCurrentUtteranceIdRef.current;
                if (!utteranceId) return;
                await sendChunkBlob(evt.data, socket, sid, mimeType || "audio/webm", utteranceId);
            };
            const makeRecorderErrorHandler = () => (evt: any) => {
                console.error("[VOICE] recorder error", evt);
                setVoiceWsState("error");
            };

            const createRecorder = () => {
                const rec = mimeType
                    ? new MediaRecorder(stream, { mimeType })
                    : new MediaRecorder(stream);
                rec.ondataavailable = makeChunkHandler();
                rec.onerror = makeRecorderErrorHandler();
                return rec;
            };

            const recorder = createRecorder();
            mediaRecorderRef.current = recorder;

            restartRecorderRef.current = () => {
                const oldRec = mediaRecorderRef.current;
                if (oldRec) {
                    oldRec.ondataavailable = null;
                    if (oldRec.state !== "inactive") oldRec.stop();
                }
                // Discard stale pre-roll and header from the old recorder
                preRollChunksRef.current = [];
                webmHeaderBlobRef.current = null;
                const newRec = createRecorder();
                mediaRecorderRef.current = newRec;
                newRec.start(VOICE_CHUNK_MS);
                console.log("[VOICE] recorder restarted for fresh webm container");
            };

            recorder.start(VOICE_CHUNK_MS);
            await setupMicVad(stream, ws, mimeType || "audio/webm");
            setVoiceModeEnabled(true);
        } catch (e: any) {
            console.error("[VOICE] start failed", e);
            setVoiceError(e?.message || "voice mode start failed");
            setVoiceWsState("error");
            await stopVoiceMode();
        }
    };

